<?php
declare(strict_types=1);
$root=__DIR__.'/.shared-learning-sandbox'; @mkdir($root); @mkdir($root.'/includes'); @mkdir($root.'/storage');
copy(__DIR__.'/../../functions.php',$root.'/functions.php');
foreach(['invoice_voice_learning.php','invoice_shared_learning.php','invoice_catalog.php','logger.php','email_transport.php'] as $f) copy(__DIR__.'/../../includes/'.$f,$root.'/includes/'.$f);
file_put_contents($root.'/storage/.htaccess', "Require all denied\n");
require $root.'/functions.php'; require $root.'/includes/invoice_catalog.php'; require $root.'/includes/invoice_voice_learning.php'; require $root.'/includes/invoice_shared_learning.php';
$n=0; $assert=static function(bool $ok,string $message)use(&$n):void{$n++;if(!$ok)throw new RuntimeException($message);};
$a=str_repeat('a',32); $b=str_repeat('b',32); $id=str_repeat('c',32);
$admin=['id'=>$b,'role'=>'admin','auth_source'=>'personal','name'=>'Admin'];
$staff=['id'=>$a,'role'=>'staff','auth_source'=>'personal'];
$users=[['id'=>$a,'active'=>true,'name'=>'Alice'],['id'=>$b,'active'=>true,'name'=>'Admin']];
$assert(!portal_voice_learning_update($a,'share_on',[])['ok'],'Sharing requires personal learning');
portal_voice_learning_update($a,'start',[]);
portal_voice_learning_update($a,'correction',['heard'=>'Rutt byte','approved'=>'Glasbyte']);
$assert(portal_voice_learning_read($a)['share_learning']===false && portal_voice_shared_candidates($admin,$users,[])===[],'Existing corrections remain private until opt in');
$assert(portal_voice_learning_update($a,'share_on',[])['profile']['share_learning'],'Explicit opt in');
$article=['id'=>$id,'name'=>'Glasbyte','unit'=>'st','price'=>750.25,'fixed_price'=>true,'aliases'=>[],'created_at'=>'2026-01-01T00:00:00Z'];
$assert(save_data(portal_invoice_catalog_path(),[$article]),'Create fixed item');
$rows=portal_voice_shared_candidates($admin,$users,[$article]);
$assert(count($rows)===1 && $rows[0]===['source_id'=>$a,'source_name'=>'Alice','heard'=>'Rutt byte','approved'=>'Glasbyte'],'Only description and source exposed');
$assert(portal_voice_shared_candidates($staff,$users,[$article])===[], 'Staff denied');
$central=$admin; $central['auth_source']='central_admin';
$assert(portal_voice_shared_candidates($central,$users,[$article])===[] && !portal_voice_shared_approve($central,$users,$a,'Rutt byte','Glasbyte',$id)['ok'] && !portal_voice_shared_approve($staff,$users,$a,'Rutt byte','Glasbyte',$id)['ok'],'Central admin and staff forbidden');
$inactive=$users; $inactive[0]['active']=false;
$assert(portal_voice_shared_candidates($admin,$inactive,[$article])===[] && !portal_voice_shared_approve($admin,$inactive,$a,'Rutt byte','Glasbyte',$id)['ok'],'Inactive contributor rejected');
$assert(!portal_voice_shared_approve($admin,$users,$a,'Rutt byte','Manipulerad',$id)['ok'] && !portal_voice_shared_approve($admin,$users,$a,'Rutt byte','Glasbyte',str_repeat('d',32))['ok'],'Tampered correction and missing target rejected');
portal_voice_learning_update($a,'share_off',[]);
$assert(!portal_voice_shared_approve($admin,$users,$a,'Rutt byte','Glasbyte',$id)['ok'] && portal_voice_shared_candidates($admin,$users,[$article])===[],'Opt out invalidates old forms');
portal_voice_learning_update($a,'share_on',[]);
portal_voice_learning_update($a,'correction',['heard'=>'Rutt byte','approved'=>'Annan']);
$assert(!portal_voice_shared_approve($admin,$users,$a,'Rutt byte','Glasbyte',$id)['ok'],'Changed correction invalidates old form');
portal_voice_learning_update($a,'correction',['heard'=>'Rutt byte','approved'=>'Glasbyte']);
$result=portal_voice_shared_approve($admin,$users,$a,'Rutt byte','Glasbyte',$id);
$assert($result['ok'],'Approval saves');
$saved=portal_invoice_catalog_list()[0];
$assert($saved['aliases']===['Rutt byte'] && $saved['price']===750.25 && $saved['unit']==='st' && $saved['fixed_price']===true,'Only alias changes, never price unit or lock');
$assert(!portal_voice_shared_approve($admin,$users,$a,'Rutt byte','Glasbyte',$id)['ok'] && portal_voice_shared_candidates($admin,$users,[$saved])===[],'Duplicate and already known names are blocked');
// Another contributor participates only after their own explicit consent.
portal_voice_learning_update($b,'start',[]);
portal_voice_learning_update($b,'correction',['heard'=>'Glaas','approved'=>'Glasbyte']);
$assert(portal_voice_shared_candidates($admin,$users,portal_invoice_catalog_list())===[],'Other account remains private');
portal_voice_learning_update($b,'share_on',[]);
$assert(count(portal_voice_shared_candidates($admin,$users,portal_invoice_catalog_list()))===1,'Other consenting account contributes');
portal_voice_learning_update($b,'correction',['heard'=>'Glaas','approved'=>'Glasbyte']);
portal_voice_learning_update($b,'correction',['heard'=>'Rutt byte','approved'=>'Glasbyte']);
$summary=portal_voice_shared_article_summary($admin,$users,portal_invoice_catalog_list());
$matching=array_values(array_filter($summary,static fn($r)=>$r['heard']==='Rutt byte'));
$assert(count($matching)===1 && $matching[0]['contributors']===2 && $matching[0]['article_name']==='Glasbyte', 'Two consenting accounts counted once each, including existing aliases');
$assert(portal_voice_shared_article_summary($staff,$users,portal_invoice_catalog_list())===[] && portal_voice_shared_article_summary($central,$users,portal_invoice_catalog_list())===[], 'Only personal invoice admins can read summary');
portal_voice_learning_update($b,'share_off',[]);
$summary=portal_voice_shared_article_summary($admin,$users,portal_invoice_catalog_list());
$matching=array_values(array_filter($summary,static fn($r)=>$r['heard']==='Rutt byte'));
$assert(count($matching)===1 && $matching[0]['contributors']===1, 'Opt-out immediately removes account from aggregate');
portal_voice_learning_update($b,'share_on',[]);
$ambiguous=portal_invoice_catalog_list(); $another=$article; $another['id']=str_repeat('9',32); $ambiguous[]=$another;
$assert(portal_voice_shared_article_summary($admin,$users,$ambiguous)===[], 'Ambiguous targets are not counted');
// A name matching any other article is never added, even from a stale form.
portal_voice_learning_update($a,'correction',['heard'=>'Annat namn','approved'=>'Glasbyte']);
$otherId=str_repeat('f',32);
$raw=portal_invoice_catalog_read(); $raw[]=['id'=>$otherId,'name'=>'Annat namn','unit'=>'st','price'=>1,'fixed_price'=>false,'aliases'=>[]];
$assert(save_data(portal_invoice_catalog_path(),$raw),'Create conflicting item');
$assert(!portal_voice_shared_approve($admin,$users,$a,'Annat namn','Glasbyte',$id)['ok'],'Existing name conflict is rejected');
// Normalization rounds legacy prices and defaults unknown units; approval must not.
$legacyId=str_repeat('e',32);
$legacyItem=['id'=>$legacyId,'name'=>'Annat','unit'=>'legacy-unit','price'=>123.456,'fixed_price'=>false,'aliases'=>[],'custom'=>'untouched'];
$raw=portal_invoice_catalog_read(); $raw[]=$legacyItem; $assert(save_data(portal_invoice_catalog_path(),$raw),'Create legacy item');
portal_voice_learning_update($a,'correction',['heard'=>'Anat','approved'=>'Annat']);
$assert(portal_voice_shared_approve($admin,$users,$a,'Anat','Annat',$legacyId)['ok'],'Legacy item approval');
$raw=portal_invoice_catalog_read(); $last=end($raw);
$assert($last['price']===123.456 && $last['unit']==='legacy-unit' && $last['custom']==='untouched','Raw legacy price, unit and metadata preserved');
portal_voice_learning_update($a,'pause',[]);
$assert(!portal_voice_learning_read($a)['share_learning'],'Pause stops sharing');
portal_voice_learning_update($a,'start',[]);
$assert(!portal_voice_learning_read($a)['share_learning'],'Restart does not silently reshare');
portal_voice_learning_update($a,'forget',[]);
$savedById=array_values(array_filter(portal_invoice_catalog_list(), static fn($item)=>$item['id']===$id));
$assert(count($savedById)===1 && $savedById[0]['aliases']===['Rutt byte'],'Approved alias survives forgetting');
$legacy=portal_voice_learning_empty(); unset($legacy['share_learning']); save_data(portal_voice_learning_path($a),$legacy);
$assert(portal_voice_learning_read($a)['share_learning']===false,'Legacy profiles are opted out');
foreach(glob($root.'/storage/*') ?: [] as $f) unlink($f); unlink($root.'/storage/.htaccess'); rmdir($root.'/storage');
foreach(glob($root.'/includes/*') ?: [] as $f) unlink($f); rmdir($root.'/includes'); unlink($root.'/functions.php'); rmdir($root);
echo "PASS: {$n} shared voice learning checks.\n";
